/**
 * `diff`: two captures of one cell, per-quantity deltas, and — for each
 * proposal that was applied between them — its `predictionError`.
 *
 * The quantities a report is compared on are read off two `measure` reports by
 * one function ({@link densityReportQuantities}), which `plan` uses for its
 * predicted deltas too: a prediction and its re-measurement are read the same
 * way. Each quantity is a number, an interval `{ lo, hi }` (`answeredAt[k]`),
 * or `null` when the report does not know it. Nothing is combined: scroll,
 * interactions and shares stay separate quantities, and no quantity is summed
 * across asks, roles or cells.
 *
 * A delta is `after − before`; for intervals it is the interval of possible
 * differences, `{ lo: after.lo − before.hi, hi: after.hi − before.lo }`; with
 * either side unknown it is `null`. A prediction error is `measured −
 * predicted`, endpoint by endpoint for an interval.
 *
 * Plan: 2026-11-23-ui-bridge-measures-information-density-as-reach-per-role-and-plans-the-change (Phase 7).
 */

import { Observation, type ObservationTime } from '../observation/observation';
import { densityTargetsHash, hashDensityCanonical } from './hash';
import { measureDensity, type DensityMeasureReport } from './measure';
import { DENSITY_QUANTITIES, densityQuantityValues, type DensityQuantityAt } from './quantities';
import type { DensityFloors } from './reach';
import {
  DENSITY_CAPTURE_SCHEMA,
  type DensityCapture,
  type DensityCell,
  type DensityProducer,
  type DensityTargets,
} from './schema';

/** A quantity's value: a number, an interval (an end `null` where it has no bound), or `null` (unknown). */
export type DensityDeltaValue = number | { lo: number | null; hi: number | null } | null;

/** One quantity that differs between two reports. */
export interface DensityDelta {
  quantity: string;
  before: DensityDeltaValue;
  after: DensityDeltaValue;
  delta: DensityDeltaValue;
}

/**
 * The longest delta list a `diff` prints; the rest is counted. A prediction
 * that `plan` records is never capped: `diff` reads every one of its deltas back.
 */
export const DENSITY_DELTA_LIST_CAP = 200;

/** The hash a prediction records of the capture it was made from: `diff` checks it. */
export function densityCaptureHash(capture: DensityCapture): string {
  return hashDensityCanonical(capture);
}

/** The key of one value of a quantity: its id, and what it belongs to. */
function keyOf(id: string, at: DensityQuantityAt): string {
  const parts: string[] = [];
  for (const k of ['ask', 'block', 'repeat', 'affordance', 'kind'] as const) {
    if (at[k] !== undefined) parts.push(`${k}=${at[k]}`);
  }
  if (at.remainder) parts.push('remainder');
  return parts.length === 0 ? id : `${id}[${parts.join(',')}]`;
}

/**
 * Every quantity of a report, by key: each value of each registered quantity
 * (`DENSITY_QUANTITIES`), keyed `<quantity id>` or `<quantity id>[ask=B2]`
 * (`block=…`, `repeat=…`, `affordance=…`, `kind=…`), so every delta names a
 * quantity with a unit and a definition. A point interval reads as its number,
 * an interval as `{ lo, hi }` (`hi` `null`: no upper bound), an unknown as
 * `null`.
 */
export function densityReportQuantities(
  report: DensityMeasureReport
): Map<string, DensityDeltaValue> {
  const q = new Map<string, DensityDeltaValue>();
  for (const quantity of DENSITY_QUANTITIES) {
    for (const v of densityQuantityValues(report, quantity)) {
      const key = keyOf(quantity.id, v.at);
      if ('unknown' in v.value) q.set(key, null);
      else q.set(key, v.value.hi === v.value.lo ? v.value.lo : { lo: v.value.lo, hi: v.value.hi });
    }
  }
  return q;
}

function isInterval(v: DensityDeltaValue): v is { lo: number | null; hi: number | null } {
  return v !== null && typeof v === 'object';
}

function asInterval(v: number | { lo: number | null; hi: number | null }) {
  return typeof v === 'number' ? { lo: v, hi: v } : v;
}

function same(a: DensityDeltaValue, b: DensityDeltaValue): boolean {
  if (isInterval(a) && isInterval(b)) return a.lo === b.lo && a.hi === b.hi;
  return a === b;
}

/** A value as a number when its interval is a point. */
function tidy(v: { lo: number | null; hi: number | null }): DensityDeltaValue {
  return v.lo !== null && v.lo === v.hi ? v.lo : v;
}

/**
 * `after − before`, as {@link DensityDelta} defines it: the interval of
 * possible differences, an end `null` where a bound is missing; `null` when
 * either side is unknown.
 */
function difference(after: DensityDeltaValue, before: DensityDeltaValue): DensityDeltaValue {
  if (after === null || before === null) return null;
  if (typeof after === 'number' && typeof before === 'number') return after - before;
  const a = asInterval(after);
  const b = asInterval(before);
  return tidy({
    lo: a.lo === null || b.hi === null ? null : a.lo - b.hi,
    hi: a.hi === null || b.lo === null ? null : a.hi - b.lo,
  });
}

/**
 * The quantities that differ between two reports, in id order; how many did
 * not; and how many are unknown on both sides (neither changed nor unchanged:
 * an unknown never reads as a match).
 */
export function densityDeltas(
  before: ReadonlyMap<string, DensityDeltaValue>,
  after: ReadonlyMap<string, DensityDeltaValue>
): { deltas: DensityDelta[]; unchanged: number; unknownBoth: number } {
  const ids = [...new Set([...before.keys(), ...after.keys()])].sort();
  const deltas: DensityDelta[] = [];
  let unchanged = 0;
  let unknownBoth = 0;
  for (const id of ids) {
    const b = before.has(id) ? before.get(id)! : null;
    const a = after.has(id) ? after.get(id)! : null;
    if (before.has(id) === after.has(id)) {
      if (a === null && b === null) {
        unknownBoth++;
        continue;
      }
      if (same(a, b)) {
        unchanged++;
        continue;
      }
    }
    deltas.push({ quantity: id, before: b, after: a, delta: difference(a, b) });
  }
  return { deltas, unchanged, unknownBoth };
}

/** A prediction of one cell, as `plan` records it and `diff` reads it back. */
export interface DensityRecordedPrediction {
  cell: DensityCell;
  /** {@link densityCaptureHash} of the capture the prediction was made from. */
  fromCapture: string;
  /** The targets the prediction was measured against (`densityTargetsHash`), or `null`. */
  targetsHash: string | null;
  /** The floors the prediction was measured against, or `null`. */
  floors: DensityFloors | null;
  /** Only the quantities the prediction changed; every other one was predicted unchanged. */
  deltas: DensityDelta[];
}

/** One quantity a prediction got wrong. */
export interface DensityPredictionMiss {
  quantity: string;
  predicted: DensityDeltaValue;
  measured: DensityDeltaValue;
  /** `measured − predicted`; `null` when either is unknown. */
  error: DensityDeltaValue;
}

/** How one applied proposal's prediction compares with the re-measurement. */
export type DensityPredictionError =
  | {
      proposal: string;
      status: 'compared';
      /** Quantities predicted exactly. */
      exact: number;
      /** Quantities unknown in the prediction and the measurement alike: not counted as exact. */
      unknown: string[];
      misses: DensityPredictionMiss[];
    }
  | { proposal: string; status: 'unknown'; code: 'input_missing'; reason: string };

function endpointError(
  measured: DensityDeltaValue,
  predicted: DensityDeltaValue
): DensityDeltaValue {
  if (measured === null || predicted === null) return null;
  if (typeof measured === 'number' && typeof predicted === 'number') return measured - predicted;
  const m = asInterval(measured);
  const p = asInterval(predicted);
  return tidy({
    lo: m.lo === null || p.lo === null ? null : m.lo - p.lo,
    hi: m.hi === null || p.hi === null ? null : m.hi - p.hi,
  });
}

/** An applied proposal handed to `diff`: its id and its recorded prediction for this cell, if any. */
export interface DensityAppliedProposal {
  id: string;
  /** `null` when the proposal recorded no prediction for this cell (it was unknown there). */
  prediction: DensityRecordedPrediction | null;
}

/** The report of one `diff`. Holds no page text. */
export interface DensityDiffReport {
  cell: DensityCell;
  before: { snapshotId: string | null; observedAt: string | null; capture: string };
  after: { snapshotId: string | null; observedAt: string | null; capture: string };
  shown: number;
  total: number;
  truncated: boolean;
  deltas: DensityDelta[];
  unchanged: number;
  /** Quantities unknown in both captures. */
  unknownBoth: number;
  predictionError: DensityPredictionError[];
}

export type DensityDiffObservation = Observation<DensityDiffReport>;

export interface DensityDiffOptions {
  producer: DensityProducer;
  targets?: DensityTargets | null;
  floors?: DensityFloors | null;
  applied?: readonly DensityAppliedProposal[];
  cap?: number;
  evaluatedAt?: ObservationTime;
}

function sameCell(a: DensityCell, b: DensityCell): boolean {
  return (
    a.role === b.role &&
    a.fixture === b.fixture &&
    a.viewport.width === b.viewport.width &&
    a.viewport.height === b.viewport.height
  );
}

/** The cell as text, for a reason. */
export function densityCellLabel(cell: DensityCell): string {
  return `${cell.role ?? '(no role)'} @ ${cell.viewport.width}x${cell.viewport.height}${cell.fixture === null ? '' : ` / ${cell.fixture}`}`;
}

/**
 * Compare two captures of one cell. Answers `unknown{input_missing}` when the
 * captures are of different cells, or when either cannot be measured.
 */
export function diffDensity(
  before: DensityCapture,
  after: DensityCapture,
  options: DensityDiffOptions
): DensityDiffObservation {
  const evaluatedAt = options.evaluatedAt ?? new Date();
  const beforeHash = densityCaptureHash(before);
  const afterHash = densityCaptureHash(after);
  const prov = Observation.provenance({
    producer: { id: options.producer.id, version: options.producer.version },
    observedAt: after.observedAt,
    evaluatedAt,
    coverage: after.coverage,
    source: {
      package: options.producer.package,
      schema: DENSITY_CAPTURE_SCHEMA,
      before: beforeHash,
      after: afterHash,
    },
  });
  if (!sameCell(before.cell, after.cell)) {
    return Observation.unknown(
      'input_missing',
      `diff compares two captures of one cell, and these are of ${densityCellLabel(before.cell)} and ${densityCellLabel(after.cell)}`,
      prov
    );
  }
  const measureOpts = {
    producer: options.producer,
    targets: options.targets ?? null,
    floors: options.floors ?? null,
    cap: Number.MAX_SAFE_INTEGER,
    evaluatedAt,
  };
  const b = measureDensity(before, { ...measureOpts, captures: [before] });
  const a = measureDensity(after, { ...measureOpts, captures: [after] });
  if (b.status !== 'measured' || a.status !== 'measured') {
    const which = b.status !== 'measured' ? 'before' : 'after';
    const obs = b.status !== 'measured' ? b : a;
    const detail = obs.status === 'unknown' ? obs.unknown.detail : 'no report';
    return Observation.unknown(
      'input_missing',
      `the ${which} capture cannot be measured: ${detail}`,
      prov
    );
  }
  const qb = densityReportQuantities(b.value);
  const qa = densityReportQuantities(a.value);
  const { deltas, unchanged, unknownBoth } = densityDeltas(qb, qa);
  const targetsHash = options.targets ? densityTargetsHash(options.targets) : null;
  const floors = options.floors ?? null;
  const cap = options.cap ?? DENSITY_DELTA_LIST_CAP;
  const shownDeltas = deltas.slice(0, Math.max(0, cap));

  const predictionError: DensityPredictionError[] = (options.applied ?? []).map((p) => {
    if (p.prediction === null) {
      return {
        proposal: p.id,
        status: 'unknown',
        code: 'input_missing',
        reason: 'the proposal recorded no prediction for this cell',
      };
    }
    if (p.prediction.fromCapture !== beforeHash) {
      return {
        proposal: p.id,
        status: 'unknown',
        code: 'input_missing',
        reason: 'the proposal was predicted from a different capture than --before',
      };
    }
    if (p.prediction.targetsHash !== targetsHash) {
      return {
        proposal: p.id,
        status: 'unknown',
        code: 'input_missing',
        reason: 'the proposal was predicted against other targets than this diff measures with',
      };
    }
    const pf = p.prediction.floors;
    const sameFloors =
      pf === null || floors === null
        ? pf === floors
        : pf.fontPx === floors.fontPx &&
          pf.lineHeightRatio === floors.lineHeightRatio &&
          pf.targetPx === floors.targetPx &&
          pf.rowPadPx === floors.rowPadPx;
    if (!sameFloors) {
      return {
        proposal: p.id,
        status: 'unknown',
        code: 'input_missing',
        reason: 'the proposal was predicted against other floors than this diff measures with',
      };
    }
    const predicted = new Map(qb);
    for (const d of p.prediction.deltas) predicted.set(d.quantity, d.after);
    const ids = [...new Set([...predicted.keys(), ...qa.keys()])].sort();
    let exact = 0;
    const unknown: string[] = [];
    const misses: DensityPredictionMiss[] = [];
    for (const id of ids) {
      const pv = predicted.get(id) ?? null;
      const mv = qa.get(id) ?? null;
      if (pv === null && mv === null) {
        unknown.push(id);
        continue;
      }
      if (same(pv, mv)) {
        exact++;
        continue;
      }
      misses.push({ quantity: id, predicted: pv, measured: mv, error: endpointError(mv, pv) });
    }
    return { proposal: p.id, status: 'compared', exact, unknown, misses };
  });

  return Observation.measured(
    {
      cell: after.cell,
      before: { snapshotId: before.snapshotId, observedAt: before.observedAt, capture: beforeHash },
      after: { snapshotId: after.snapshotId, observedAt: after.observedAt, capture: afterHash },
      shown: shownDeltas.length,
      total: deltas.length,
      truncated: shownDeltas.length < deltas.length,
      deltas: shownDeltas,
      unchanged,
      unknownBoth,
      predictionError,
    },
    prov
  );
}
